import sys, json

def trunc(s, n=300):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def summarize_content(content):
    if isinstance(content, str):
        return trunc(content)
    if isinstance(content, list):
        parts = []
        for c in content:
            if not isinstance(c, dict):
                parts.append(trunc(c, 150))
                continue
            t = c.get("type")
            if t == "text":
                parts.append(trunc(c.get("text", ""), 300))
            elif t == "tool_use":
                parts.append(f"[TOOL_USE {c.get('name')} input={trunc(json.dumps(c.get('input', {})), 250)}]")
            elif t == "tool_result":
                cont = c.get("content")
                if isinstance(cont, list):
                    cont = " ".join(trunc(x.get("text",""),200) for x in cont if isinstance(x,dict))
                parts.append(f"[TOOL_RESULT err={c.get('is_error')} {trunc(cont,250)}]")
            elif t == "thinking":
                parts.append(f"[THINKING {trunc(c.get('thinking',''), 200)}]")
            else:
                parts.append(f"[{t} {trunc(c,150)}]")
        return " | ".join(parts)
    return trunc(content, 300)

path = sys.argv[1]
with open(path) as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception as e:
            print(f"{i}: PARSE_ERROR {e}")
            continue
        ts = d.get("timestamp", "")
        typ = d.get("type", d.get("operation",""))
        if typ == "queue-operation":
            print(f"{i} {ts} QUEUE[{d.get('operation')}] {trunc(d.get('content'), 200)}")
            continue
        if "attachment" in d:
            att = d["attachment"]
            print(f"{i} {ts} ATTACH[{att.get('hookName') or att.get('type')}] {trunc(att.get('content') or att.get('stdout',''), 200)}")
            continue
        msg = d.get("message")
        if msg:
            role = msg.get("role")
            content = msg.get("content")
            print(f"{i} {ts} {typ}/{role}: {summarize_content(content)}")
            continue
        print(f"{i} {ts} {typ}: {trunc(d, 200)}")

